# Viva deep redo — slot R2 (part A): warts, herpes zoster, mycetoma, sporotrichosis, chromoblastomycosis, tinea corporis
# Own words. Topics guided by the previous-year question book (Sahana P Raju) — viral (HHV, zoster, PHN, HPV),
# fungal (classification, subcutaneous mycoses) chapters; facts checked with IADVL 5e (ch. 19A deep fungal etc.).
PYQ = "Previous-year PG question papers (Sahana P Raju, Solved Papers Dermatology)"
IA = "IADVL Textbook of Dermatology 5e"

D = [
dict(case="Warts (verruca)", src=f"{PYQ}; {IA} (Viral infections — HPV)",
 qa=[
 ("What are warts? Name the virus.", ["Benign epidermal proliferations caused by human papillomavirus (HPV) — non-enveloped double-stranded circular DNA virus, Papillomaviridae; >200 types", "Infects basal keratinocytes through micro-abrasions; replicates as cells differentiate; causes koilocytes"]),
 ("Classify cutaneous and mucosal warts with HPV types.", ["Common warts (verruca vulgaris): HPV 2, 4 (27, 57)", "Plantar (myrmecia, deep): HPV 1; mosaic plantar: HPV 2", "Plane (flat) warts: HPV 3, 10", "Butcher's warts: HPV 7", "Anogenital warts (condyloma acuminata): HPV 6, 11 (low risk) — high-risk 16, 18, 31, 33 cause intraepithelial neoplasia", "Epidermodysplasia verruciformis: HPV 5, 8 (beta-HPV)", "Oral: focal epithelial hyperplasia (Heck's disease) HPV 13, 32; recurrent respiratory papillomatosis HPV 6, 11", "Bowenoid papulosis and Buschke–Löwenstein tumour (giant condyloma, HPV 6, 11)"]),
 ("Describe the clinical types.", ["Common: rough hyperkeratotic papules, fingers/hands/knees; periungual (nail biters); filiform on face/neck", "Plantar: inward-growing painful papule with surrounding callus; interrupted dermatoglyphics; black dots (thrombosed capillaries) on paring", "Plane: flat-topped smooth skin-coloured or brown papules on face/backs of hands; linear in scratch lines (Koebner/pseudo-Koebner)", "Anogenital: soft papillomatous, sessile or pedunculated papules (cauliflower-like)"]),
 ("How do you differentiate a plantar wart from a corn (clavus)?", ["Wart: interrupts skin lines, black dots on paring, pain on lateral squeeze (pinching), multiple, not necessarily on pressure points", "Corn: skin lines pass through, central translucent core, no black dots, pain on direct pressure, at pressure points"]),
 ("Histopathology of a wart?", ["Hyperkeratosis with parakeratosis in columns over papillomatous peaks, acanthosis, elongated rete ridges bending inwards ('arborisation')", "Koilocytes (vacuolated keratinocytes with pyknotic nucleus and perinuclear halo) in upper spinous/granular layer, coarse keratohyaline granules, dilated capillaries in dermal papillae", "Myrmecia: large eosinophilic intracytoplasmic inclusions"]),
 ("Differential diagnosis.", ["Common: seborrhoeic keratosis, actinic keratosis, SCC/keratoacanthoma, molluscum, TBVC, lichen planus hypertrophic, acrokeratosis verruciformis of Hopf", "Plane: lichen planus, lichen nitidus, syringomas, epidermodysplasia verruciformis, milia", "Genital: pearly penile papules, Fordyce spots, vestibular papillae, condyloma lata (secondary syphilis — moist, flat), molluscum, bowenoid papulosis, seborrhoeic keratosis"]),
 ("Treatment options — classify.", ["Destructive: chemical — salicylic acid 12–26%/lactic acid (first line, cheap), trichloroacetic acid, podophyllin 20–25%/podophyllotoxin 0.5% (genital; not in pregnancy), cantharidin, glutaraldehyde, formaldehyde", "Physical — cryotherapy (liquid nitrogen, every 2–3 weeks), electrocautery/radiofrequency ablation, curettage, CO2/Er:YAG laser, pulsed-dye laser", "Antiproliferative: 5-fluorouracil, bleomycin intralesional, cidofovir, retinoids (plane warts)", "Immunotherapy: imiquimod 5% (genital), sinecatechins, contact sensitisers (DPCP, SADBE), intralesional antigens (MMR, Candida, PPD, Mw vaccine, vitamin D3), oral zinc, cimetidine (weak evidence)"]),
 ("What is intralesional immunotherapy? Mention the principle.", ["Injecting an antigen (MMR vaccine, Candida antigen, PPD, Mycobacterium w/MIP, vitamin D3) into one or a few warts induces a Th1 cell-mediated response that clears distant untreated warts too", "Useful for multiple, recalcitrant warts; side effects — pain, flu-like illness; avoid in immunosuppressed and pregnancy (live vaccines)"]),
 ("Management of anogenital warts.", ["Patient-applied: podophyllotoxin 0.5% solution/0.15% cream (3 days on, 4 off, up to 4 cycles), imiquimod 5% (3 nights/week up to 16 weeks), sinecatechins 15%", "Provider: cryotherapy, TCA 80–90%, podophyllin 25%, electrocautery, excision, laser", "Pregnancy: cryotherapy/TCA/excision — avoid podophyllin, imiquimod relatively avoided", "Screen for other STIs, examine partner, Pap smear in women; condom use", "In children — consider sexual abuse but also non-sexual (vertical, autoinoculation, hetero-inoculation)"]),
 ("What is epidermodysplasia verruciformis? (short note)", ["Rare inherited (mostly autosomal recessive — TMC6/EVER1, TMC8/EVER2, CIB1) susceptibility to beta-HPV (5, 8)", "Widespread plane-wart-like papules and pityriasis versicolor-like macules from childhood", "~30–60% develop SCC on sun-exposed skin in 4th–5th decade — strict photoprotection; acquired form in HIV/transplant"]),
 ("Which HPV vaccines are available? Schedule?", ["Bivalent (16, 18), quadrivalent (6, 11, 16, 18), nonavalent (adds 31, 33, 45, 52, 58), Indian quadrivalent Cervavac (Serum Institute, 2022)", "Best before sexual debut — 9–14 years: 2 doses 6 months apart; ≥15 y: 3 doses (0, 1–2, 6 months); WHO now also allows single dose", "India: HPV vaccination for girls 9–14 years announced for national programme"]),
 ("Why are warts common and recalcitrant in transplant recipients?", ["Impaired cell-mediated immunity; HPV persists and lesions progress to SCC (beta-HPV with UV as co-factor)"]),
 ("What is Buschke–Löwenstein tumour?", ["Giant condyloma acuminatum (HPV 6/11) — locally destructive, verrucous carcinoma-like; treat with wide surgical excision"]),
 ("What is bowenoid papulosis?", ["Multiple small reddish-brown flat papules on genitals of young adults (HPV 16) — histology of SCC in situ, behaviour usually benign; partners risk cervical neoplasia"]),
 ("Prognosis of untreated common warts?", ["About two-thirds of warts in children resolve spontaneously within 2 years; regression may show blackening"]),
 ],
 spot=["Black dots + interrupted dermatoglyphics — plantar wart", "Koilocytes — HPV", "HPV 5, 8 — epidermodysplasia verruciformis with SCC risk"]),

dict(case="Herpes zoster", src=f"{PYQ}; {IA} (Viral infections — VZV)",
 qa=[
 ("Define herpes zoster. What is its pathogenesis?", ["Reactivation of latent varicella-zoster virus from a sensory (dorsal root or cranial nerve) ganglion, producing painful unilateral dermatomal vesicular eruption", "Fall in VZV-specific cell-mediated immunity with age (>50 y), HIV, malignancy (lymphoma), chemotherapy, steroids, JAK inhibitors, transplant, stress, trauma", "Virus travels down the sensory nerve to skin; ganglionitis causes pain"]),
 ("Which dermatomes are commonly affected?", ["Thoracic (T3–L2) commonest (~50%), then trigeminal (ophthalmic division), cervical, lumbosacral", "Usually one dermatome; may involve adjacent ones; crosses midline only slightly"]),
 ("Describe the clinical course.", ["Prodrome 1–5 days: burning, itching, pain (may mimic angina, cholecystitis, renal colic), fever, malaise", "Erythematous papules → grouped vesicles in a band along the dermatome → pustules → crusts by 7–10 days; heals in 2–4 weeks", "Zoster sine herpete: pain without rash", "Few vesicles (<20) outside the dermatome are allowed; more suggests dissemination"]),
 ("What is disseminated zoster?", ["More than 20 vesicles outside the primary and adjacent dermatomes, or ≥3 dermatomes involved, or visceral involvement — implies immunosuppression (HIV, malignancy); needs IV acyclovir"]),
 ("What is herpes zoster ophthalmicus and Hutchinson's sign?", ["Zoster of the ophthalmic division of trigeminal nerve (V1)", "Hutchinson's sign: vesicles on the tip/side of nose (external nasal branch of nasociliary nerve) — high risk of eye involvement (keratitis, uveitis, glaucoma, retinitis, optic neuritis)", "Needs ophthalmology referral and systemic antivirals"]),
 ("What is Ramsay Hunt syndrome?", ["Zoster of geniculate ganglion of facial nerve — ipsilateral lower motor neurone facial palsy, ear pain, vesicles on the ear (concha, external canal), taste loss in anterior 2/3 of tongue, tinnitus, vertigo, hearing loss", "Worse recovery than Bell's palsy — antivirals + prednisolone early"]),
 ("Name other complications.", ["Post-herpetic neuralgia (commonest)", "Secondary bacterial infection, scarring, pigmentation, Koebner (granulomatous/ lichenoid lesions at healed sites — Wolf's isotopic response)", "Motor palsy (e.g. foot drop, bladder dysfunction in sacral zoster, abdominal wall pseudohernia)", "Meningoencephalitis, myelitis, Guillain–Barré, stroke (VZV vasculopathy — granulomatous arteritis), pneumonitis, hepatitis"]),
 ("Define post-herpetic neuralgia (PHN) and its risk factors. (short note)", ["Pain persisting ≥90 days (3 months) after rash onset (some use 1 month)", "Risk: older age (>50), severe prodromal pain, severe acute pain, extensive rash, ophthalmic involvement, immunosuppression, diabetes, delayed antiviral therapy", "Pain types: burning, lancinating, allodynia (pain to light touch — very characteristic)"]),
 ("Management of PHN.", ["First line: pregabalin (75–300 mg twice daily) or gabapentin (titrate to 1800–3600 mg/day); tricyclics — amitriptyline/nortriptyline 10–75 mg at night", "Topical: lidocaine 5% patch, capsaicin 0.075% cream or 8% patch", "Second line: tramadol, opioids; duloxetine; nerve blocks; TENS", "Prevention: early antiviral, adequate acute pain control, vaccination"]),
 ("How do you treat acute zoster?", ["Antivirals ideally within 72 h of rash onset (later if new vesicles still forming, ophthalmic, immunosuppressed): acyclovir 800 mg five times daily × 7 days; valacyclovir 1 g thrice daily × 7 days; famciclovir 500 mg thrice daily × 7 days", "IV acyclovir 10 mg/kg 8-hourly for disseminated/immunocompromised/CNS involvement", "Adjust dose for renal function", "Analgesics (paracetamol/NSAIDs, pregabalin for severe acute pain), calamine, wet compresses, antibiotics for secondary infection", "Systemic steroids do not prevent PHN — only for Ramsay Hunt/ocular inflammation under supervision"]),
 ("What is the Tzanck smear and PCR role?", ["Tzanck — multinucleated giant cells; cannot differentiate HSV vs VZV", "PCR of vesicle fluid is the test of choice for atypical or zoster sine herpete (PCR on CSF/blood)"]),
 ("Differentiate herpes zoster from zosteriform herpes simplex.", ["HSV: recurrent at the same site, smaller grouped vesicles, less pain, no PHN, younger patients", "Zoster: usually once (recurrence in ~5%), dermatomal band, severe pain, older age, PHN risk", "PCR settles it"]),
 ("Differential diagnosis of herpes zoster.", ["Zosteriform HSV, contact dermatitis (linear plant contact), bullous impetigo, insect bites, fixed drug eruption, linear lichen planus/porokeratosis (chronic, no pain)", "Prodrome mimics: myocardial infarction, renal colic, appendicitis, migraine"]),
 ("What are zosteriform lesions? (asked in PYQ)", ["Lesions arranged in a band along a dermatome but not due to VZV — zosteriform herpes simplex, zosteriform metastases (breast cancer), zosteriform lichen planus, segmental vitiligo, zosteriform naevi, segmental neurofibromatosis, zosteriform leiomyomas", "Contrast with blaschkoid (follow Blaschko's lines — mosaic genetic disorders)"]),
 ("Why should you test for HIV in zoster?", ["Zoster in a young adult (<50 y), multi-dermatomal, recurrent, disseminated, necrotic/chronic verrucous lesions may be the first sign of HIV — offer HIV test"]),
 ("Zoster vaccines?", ["Recombinant zoster vaccine (RZV, Shingrix — gE glycoprotein + AS01B adjuvant): 2 doses IM 2–6 months apart; ≥50 years and ≥18 years if immunocompromised; ~90% efficacy; non-live, safe in immunocompromised (available in India since 2023)", "Live attenuated zoster vaccine (Zostavax) — discontinued in many countries; contraindicated in immunosuppression", "Reduces zoster and PHN"]),
 ("Is zoster contagious?", ["Yes — vesicle fluid can give chickenpox (not zoster) to non-immune people; cover lesions; airborne precautions for disseminated zoster or immunocompromised patients"]),
 ("Zoster in pregnancy?", ["Fetal risk is minimal (maternal antibodies present); treat mother with acyclovir if needed"]),
 ],
 spot=["Unilateral dermatomal grouped vesicles with pain — zoster", "Hutchinson's sign — nasal tip vesicles → eye involvement", "PHN = pain ≥90 days; allodynia"]),

dict(case="Mycetoma (Madura foot)", src=f"{PYQ}; {IA} ch. 19A (Subcutaneous mycoses — mycetoma, Tables 19A.8–19A.10)",
 qa=[
 ("Define mycetoma. What is the classic triad?", ["Chronic, progressive, granulomatous, subcutaneous infection caused by fungi (eumycetoma) or aerobic filamentous bacteria (actinomycetoma) after traumatic implantation (thorn prick)", "Triad: painless subcutaneous swelling (tumefaction), multiple sinuses, discharge of grains (granules)"]),
 ("Where is the 'mycetoma belt'? Who gets it?", ["Between latitudes ~15° S and 30° N — Sudan, Mexico, India, Senegal, Venezuela", "Barefoot farm workers and herdsmen, young adult males 20–40 years; foot commonest (~70%), then hand, back, scalp, buttocks (carrying sacks/wood)", "In India: Rajasthan, Tamil Nadu, Gujarat; actinomycetoma (Nocardia, Actinomadura) is more frequent in many Indian series, eumycetoma (Madurella) in drier areas"]),
 ("Name the causative organisms.", ["Eumycetoma: Madurella mycetomatis (commonest worldwide, black grains), Trematosphaeria grisea, Falciformispora, Scedosporium boydii (white), Acremonium, Fusarium, Exophiala", "Actinomycetoma: Nocardia brasiliensis, N. asteroides, Actinomadura madurae (white/yellow), A. pelletieri (red grains), Streptomyces somaliensis (yellow)"]),
 ("What do grain colours tell you?", ["Black grains — always eumycetoma (Madurella, Trematosphaeria, Exophiala)", "Red — Actinomadura pelletieri", "Yellow — Streptomyces somaliensis, Nocardia", "White/pale — Actinomadura madurae, Nocardia, Scedosporium, Acremonium, Fusarium"]),
 ("Compare eumycetoma and actinomycetoma.", ["Eumycetoma: slower, well-defined, encapsulated, late bone involvement with few large (>1 cm) punched-out cavities, coarse grains 0.5–2 mm (black/pale), septate hyphae with chlamydospores, treated with azoles + surgery", "Actinomycetoma: faster, ill-defined and inflammatory, early bone involvement with many small cavities ('moth-eaten'), lymph nodes more often, fine grains (20–100 µm) of thin branching Gram-positive filaments (Nocardia acid-fast), responds to antibiotics"]),
 ("How do you investigate?", ["Grains from sinus discharge, deep biopsy or FNAC — naked eye colour, KOH mount (eumycetoma: broad septate hyphae), Gram/modified ZN (actinomycetoma: thin filaments)", "Culture: Sabouraud dextrose agar (fungi); brain-heart infusion/LJ (actinomycetes); PCR/sequencing (ITS) for species", "Histopathology: suppurative granulomas around grains (type 1 neutrophils, type 2 macrophage/giant cells, type 3 epithelioid granuloma); Splendore–Hoeppli phenomenon around grains", "Imaging: X-ray (soft-tissue swelling, periosteal reaction, lytic cavities); USG (hyper-reflective grains); MRI 'dot-in-circle' sign — extent before surgery"]),
 ("What is the Splendore–Hoeppli phenomenon?", ["Radiating, eosinophilic, club-like material (antigen–antibody complexes) around organisms", "Seen in mycetoma, botryomycosis, sporotrichosis (asteroid bodies), actinomycosis, schistosomiasis, entomophthoromycosis (basidiobolomycosis)"]),
 ("What is the dot-in-circle sign?", ["On MRI/USG: small hypointense dot (grain) within hyperintense spheres (granulomatous inflammation) — highly suggestive of mycetoma"]),
 ("Treatment of actinomycetoma.", ["Combination antibiotics for months (to prevent resistance)", "Welsh regimen: amikacin 15 mg/kg/day IV + cotrimoxazole (35 mg/kg/day) for 21 days, followed by 15 days of cotrimoxazole alone; repeat 3–4 cycles; cotrimoxazole maintenance afterwards (modified Welsh — add rifampicin 10 mg/kg)", "Two-step regimen (Indian): intensive — penicillin + gentamicin + cotrimoxazole for 5–7 weeks; maintenance — amoxicillin + cotrimoxazole until 2–5 months after cure", "Modified two-step: gentamicin 80 mg IV twice daily + cotrimoxazole DS twice daily for 4 weeks, then cotrimoxazole + doxycycline 100 mg twice daily until 6 months after clinical cure", "Alternatives: dapsone, minocycline, amoxicillin-clavulanate, imipenem, linezolid; monitor renal function and hearing with aminoglycosides"]),
 ("Treatment of eumycetoma.", ["Itraconazole 200–400 mg/day (drug of choice) for many months (often 9–12+), combined with surgical debridement/excision of the reduced lesion", "Alternatives: terbinafine 250–1000 mg/day, voriconazole, posaconazole; fosravuconazole under trial", "Amputation for advanced bony disease not responding"]),
 ("What are the criteria of cure?", ["Healing of sinuses, disappearance of swelling, normal skin, no grains on FNAC/biopsy, no cavities on USG, return of normal bone on imaging; continue therapy months after clinical cure"]),
 ("Differential diagnosis.", ["Botryomycosis (bacterial grains), chronic osteomyelitis, actinomycosis (jaw, sulphur granules, anaerobic Actinomyces israelii), tuberculosis (scrofuloderma, TB of bone), chromoblastomycosis, sporotrichosis, Kaposi sarcoma, soft-tissue tumours, Madura-like cellulitis, filarial lymphoedema"]),
 ("How is actinomycosis different from actinomycetoma?", ["Actinomycosis: endogenous anaerobic Actinomyces israelii (commensal of mouth/gut), cervicofacial ('lumpy jaw'), thoracic, abdominal; sulphur granules; treat with long penicillin", "Actinomycetoma: exogenous aerobic actinomycetes (Nocardia, Actinomadura, Streptomyces), implantation on foot"]),
 ("Complications and prognosis?", ["Bone destruction, deformity, disability, secondary bacterial infection, lymphatic spread, rarely visceral spread (back mycetoma → spine, lung)", "Actinomycetoma — good cure rates with combination therapy; eumycetoma — high relapse, often surgery/amputation needed"]),
 ("Classify subcutaneous mycoses (PYQ short note).", ["Mycetoma, sporotrichosis, chromoblastomycosis, phaeohyphomycosis, entomophthoromycosis (basidiobolomycosis, conidiobolomycosis), rhinosporidiosis (now Mesomycetozoea), lobomycosis, subcutaneous zygomycosis"]),
 ("What is phaeohyphomycosis?", ["Infection by dematiaceous (brown-black) fungi that appear as pigmented septate hyphae/yeast-like cells in tissue (no muriform cells, no grains) — subcutaneous cysts (Exophiala), sinus, cerebral forms; treat with excision + itraconazole"]),
 ],
 spot=["Swelling + sinuses + grains — mycetoma", "Black grains = always fungal", "Dot-in-circle sign on MRI"]),

dict(case="Sporotrichosis", src=f"{PYQ}; {IA} ch. 19A (Subcutaneous mycoses)",
 qa=[
 ("What is sporotrichosis? Agent?", ["Subacute/chronic subcutaneous mycosis caused by the thermally dimorphic Sporothrix schenckii complex (S. schenckii, S. brasiliensis, S. globosa — commonest in Asia/India)", "Mould in environment (25 °C), yeast in tissue (37 °C)"]),
 ("How is it acquired and who gets it?", ["Implantation from soil, plants, thorns (rose — 'rose gardener's disease'), sphagnum moss, hay, wood splinters; zoonotic from cat scratches (S. brasiliensis — Brazil epidemic)", "Gardeners, farmers, florists, forestry workers; in India — sub-Himalayan belt (Himachal, north-east, Uttarakhand), Kangra valley"]),
 ("Describe the clinical types.", ["Lymphocutaneous (~75%): papulonodule at inoculation site (hand/forearm) ulcerates (sporotrichoid chancre) → secondary nodules along the lymphatic chain ascending the limb", "Fixed cutaneous: single plaque/verrucous/ulcerated lesion without lymphatic spread — common on face in children in endemic areas (more immune host)", "Disseminated cutaneous and systemic (osteoarticular, pulmonary — inhalation, meningeal) in immunosuppressed (HIV, alcoholism, diabetes)"]),
 ("What is the sporotrichoid pattern and its differentials?", ["Nodules in a linear chain along lymphatics", "Causes: sporotrichosis, Mycobacterium marinum (fish-tank granuloma), Nocardia brasiliensis, leishmaniasis (L. braziliensis), tularaemia, cat-scratch disease, other mycobacteria, blastomycosis — remember 'SLNM'"]),
 ("How do you investigate?", ["Histopathology: pseudoepitheliomatous hyperplasia, mixed suppurative granuloma ('sporotrichoid granuloma' with central neutrophils, middle histiocytes, outer lymphocytes); organisms scanty — small cigar-shaped yeasts, asteroid bodies (Splendore–Hoeppli) with PAS/GMS", "Culture on Sabouraud dextrose agar at 25 °C — the gold standard (moist white colonies becoming dark; sleeve/flower-like conidia); conversion to yeast at 37 °C", "PCR; sporotrichin skin test (epidemiology)"]),
 ("Treatment.", ["Itraconazole 100–200 mg/day (drug of choice) — continue 2–4 weeks after lesions resolve (usually 3–6 months)", "Saturated solution of potassium iodide (SSKI): start 5 drops thrice daily increased to 40–50 drops thrice daily — cheap and effective in India; side effects: metallic taste, salivary gland swelling, acneiform rash, GI upset, hypothyroidism; avoid in pregnancy", "Terbinafine 250–500 mg/day alternative; local hyperthermia (warm compresses) as adjunct — fungus does not grow above 37 °C", "Amphotericin B for disseminated/pulmonary/meningeal disease, then itraconazole"]),
 ("Differential diagnosis of fixed cutaneous sporotrichosis.", ["Lupus vulgaris, TBVC, chromoblastomycosis, leishmaniasis, pyoderma, blastomycosis, SCC, atypical mycobacterial infection"]),
 ("Why is the fixed type common on the face of children?", ["Repeated exposure in endemic areas produces strong immunity, which limits lymphatic spread"]),
 ("What is an asteroid body?", ["Central yeast surrounded by radiating eosinophilic Splendore–Hoeppli material — seen in sporotrichosis (also sarcoidosis has 'asteroid bodies' of a different kind inside giant cells)"]),
 ("Which drug is used in pregnancy?", ["Avoid azoles and iodides; local heat therapy; amphotericin B for severe disease"]),
 ],
 spot=["Ascending nodules along lymphatics from a hand ulcer — sporotrichosis", "SSKI — cheap drug that works", "Asteroid bodies"]),

dict(case="Chromoblastomycosis", src=f"{PYQ}; {IA} ch. 19A (Chromoblastomycosis)",
 qa=[
 ("What is chromoblastomycosis?", ["Chronic, slowly progressive implantation mycosis of skin and subcutis caused by dematiaceous (pigmented) fungi, producing verrucous plaques and nodules; tissue shows muriform cells"]),
 ("Name the causative agents.", ["Fonsecaea pedrosoi (~90% worldwide; F. compacta now considered the same species), Cladophialophora carrionii (arid areas), Phialophora verrucosa, Rhinocladiella aquaspersa, Exophiala species", "India: Fonsecaea pedrosoi commonest — Western Ghats, Kerala, Karnataka, Sub-Himalayan region"]),
 ("Who gets it?", ["Barefoot agricultural workers, men 30–60 years; implantation via wood splinters, thorns", "Lower limbs (foot, leg) commonest, then hands, buttocks"]),
 ("Clinical types (Carrión classification).", ["Nodular, tumorous (cauliflower-like), verrucous (commonest), plaque (scaly, slightly raised), cicatricial (atrophic centre, spreading edge)", "Black dots on the surface (transepidermal elimination of fungus) — the best sites to sample", "Satellite lesions by autoinoculation and lymphatic spread"]),
 ("What are muriform cells?", ["Thick-walled, dark-brown, round cells (4–12 µm) with septa in two planes — 'medlar bodies', 'sclerotic bodies', 'copper pennies'; the diagnostic tissue form", "Seen in KOH mount of black dots/crusts and in histology (even with H&E — pigmented)"]),
 ("Histopathology?", ["Pseudoepitheliomatous hyperplasia with intraepidermal microabscesses, transepidermal elimination", "Mixed suppurative and tuberculoid granulomas with giant cells containing muriform cells"]),
 ("Differential diagnosis.", ["TBVC, lupus vulgaris (verrucous), sporotrichosis, mycetoma (no sinuses/grains here), blastomycosis, leishmaniasis, verrucous SCC, psoriasis, lichen planus hypertrophicus, podoconiosis/elephantiasis nostras, leprosy"]),
 ("Complications?", ["Lymphoedema and elephantiasis of the limb, secondary bacterial infection, malodour, ankylosis, SCC in long-standing lesions; rarely haematogenous spread (brain — Cladophialophora bantiana)"]),
 ("Treatment.", ["Small lesions: wide surgical excision, cryotherapy, heat, CO2 laser — combined with antifungal", "Itraconazole 200–400 mg/day for 6–12 months or longer (drug of choice); terbinafine 250–500 mg/day alternative; combinations (itraconazole + terbinafine, + flucytosine); posaconazole", "Cryotherapy to reduce lesions while on itraconazole; imiquimod as immune adjunct", "Cure criteria: clinical healing + negative mycology + histology"]),
 ("Why is response poor?", ["Thick-walled muriform cells resist drugs, poor drug penetration in fibrotic tissue, chronic lesions are large at presentation"]),
 ],
 spot=["Verrucous plaque on foot with black dots — chromoblastomycosis", "Muriform / copper-penny bodies", "Fonsecaea pedrosoi"]),

dict(case="Tinea corporis / cruris / faciei", src=f"{PYQ}; {IA} (Superficial fungal infections); Indian expert consensus on dermatophytosis (2018–2023)",
 qa=[
 ("Define dermatophytosis. Classify fungal infections (common PYQ).", ["Dermatophytosis: infection of keratinised tissues (stratum corneum, hair, nails) by dermatophytes — keratinophilic moulds (Trichophyton, Microsporum, Epidermophyton; newer genera Nannizzia, Arthroderma)", "Fungal infections: superficial (pityriasis versicolor, tinea nigra, piedra), cutaneous (dermatophytosis, candidiasis), subcutaneous (mycetoma, sporotrichosis, chromoblastomycosis), systemic (histoplasmosis, cryptococcosis, blastomycosis, coccidioidomycosis, paracoccidioidomycosis, talaromycosis), opportunistic (aspergillosis, mucormycosis)"]),
 ("Classify dermatophytes by habitat.", ["Anthropophilic (human): T. rubrum, T. interdigitale (anthropophilic), T. tonsurans, T. indotineae, E. floccosum — chronic, less inflammatory", "Zoophilic (animals): M. canis, T. mentagrophytes, T. verrucosum — acute, inflammatory", "Geophilic (soil): M. gypseum (Nannizzia gypsea) — inflammatory"]),
 ("What is the current dermatophytosis situation in India?", ["Epidemic of chronic, recurrent, extensive and steroid-modified tinea since ~2014", "Main agent now Trichophyton indotineae (ITS genotype VIII of T. mentagrophytes/interdigitale complex) — anthropophilic, spreads within families", "Causes: rampant use of topical steroid–antifungal–antibiotic combinations, incomplete treatment, hot humid climate, tight synthetic clothes, crowding, fomites; terbinafine resistance via squalene epoxidase (SQLE) gene mutations (e.g. Phe397Leu, Leu393Phe)"]),
 ("Clinical features of tinea corporis.", ["Annular/arcuate plaques with raised, scaly, active edge (papules, vesicles) and central clearing; itchy; on trunk, limbs", "Variants: tinea imbricata (T. concentricum — concentric rings), bullous, Majocchi's granuloma, kerion-like, tinea profunda, pseudo-imbricata (after steroids)"]),
 ("What is tinea incognito (steroid-modified tinea)?", ["Altered appearance after topical/systemic steroids — loss of active edge, less scale, more widespread, pustules, pseudo-imbricata (concentric rings), purpura, striae, bizarre shapes", "KOH often richly positive; mimics eczema, psoriasis, lupus, rosacea (on face)"]),
 ("Describe tinea cruris and tinea faciei.", ["Cruris: groin, inner thighs, may spread to buttocks, pubis; scrotum usually spared (unlike candidiasis); men more", "Faciei: non-bearded face, photo-aggravated, often misdiagnosed as lupus or rosacea; may lack scale"]),
 ("How do you do a KOH mount and what do you see?", ["Scrape the active edge with a blunt scalpel onto slide, add 10–20% KOH (40% for nails), warm gently, coverslip", "Branched septate hyaline hyphae ± arthroconidia", "Variants: KOH with DMSO, chlorazol black E, Parker ink, calcofluor white (fluorescence) to improve sensitivity"]),
 ("Culture media and their uses (Sabouraud's — PYQ).", ["Sabouraud dextrose agar (SDA) with chloramphenicol and cycloheximide (Mycosel/Mycobiotic) — routine dermatophyte culture at 25–30 °C for up to 4 weeks", "Dermatophyte test medium (DTM) — phenol red turns red with dermatophytes", "Potato dextrose agar (pigment, sporulation), urease test (T. interdigitale positive, T. rubrum negative), hair perforation test, trichophyton agars (vitamin requirements)", "Antifungal susceptibility testing (CLSI M38) and SQLE mutation PCR in resistant cases"]),
 ("Differential diagnosis of annular lesions.", ["Nummular eczema, psoriasis, pityriasis rosea (herald patch, collarette), granuloma annulare (no scale), annular lichen planus, erythema annulare centrifugum (trailing scale), subacute cutaneous lupus, Hansen's (BT), seborrhoeic dermatitis, secondary syphilis, sarcoidosis, mycosis fungoides, erythrasma (groin)"]),
 ("Topical treatment principles.", ["Apply twice daily to lesion plus 2 cm margin, continue 2 weeks after clinical cure (usually 4–6 weeks)", "Azoles (luliconazole 1%, sertaconazole 2%, eberconazole, clotrimazole, ketoconazole), allylamines (terbinafine 1%, naftifine), amorolfine 0.25%, ciclopirox 1%", "Avoid steroid–antifungal combinations (fixed-dose combination creams)"]),
 ("Systemic treatment — Indian consensus.", ["Indications: extensive, multiple sites, recurrent/chronic, failed topical, immunosuppressed", "Itraconazole 100–200 mg/day (5 mg/kg) for 4–8 weeks — currently the most used first-line drug in India; take after a fatty meal, avoid antacids/PPIs", "Terbinafine 250–500 mg/day for 4–6 weeks (higher doses for resistant strains, though failure common with SQLE mutations)", "Griseofulvin, fluconazole (150–300 mg weekly) — less preferred now", "Combination (itraconazole + terbinafine) and voriconazole/posaconazole only for documented refractory cases; continue until clinical and mycological cure"]),
 ("What are general measures for recurrence prevention?", ["Treat all family members, wash and sun-dry clothes, iron clothes, loose cotton clothing, don't share towels, keep folds dry, weight loss, stop steroid creams, adherence to full course", "Antifungal powders/soaps as adjuncts; treat tinea pedis/onychomycosis reservoirs"]),
 ("What is Majocchi's granuloma?", ["Follicular and dermal invasion by dermatophyte (often T. rubrum) after steroid use or shaving of legs — perifollicular papulopustules/nodules; needs systemic antifungal"]),
 ("Why do we see more azole-preferred practice than terbinafine in India today?", ["T. indotineae shows high terbinafine minimum inhibitory concentrations due to SQLE mutations; itraconazole still mostly effective, though rising MIC reports exist"]),
 ("Side effects and interactions of itraconazole and terbinafine.", ["Itraconazole: CYP3A4 inhibitor — interactions (statins, warfarin, midazolam, cyclosporine), contraindicated in congestive heart failure (negative inotropy), hepatotoxicity rare, needs acidic stomach", "Terbinafine: taste disturbance, hepatotoxicity (rare), drug rash, SCLE flare, CYP2D6 inhibition (tricyclics, beta-blockers)"]),
 ("What is the id reaction (dermatophytid)?", ["Distant sterile eruption (vesicles on palms/fingers, papules) due to hypersensitivity to fungal antigen, usually with inflammatory tinea (kerion, tinea pedis); KOH negative at id site; settles when primary infection is treated"]),
 ("Name the specific special forms of tinea.", ["Tinea imbricata (T. concentricum — tribal populations, Pacific/NE India; concentric rings)", "Tinea nigra (Hortaea werneckii — brown macule on palm; not dermatophyte)", "Tinea manuum (one-hand, two-feet syndrome)", "Tinea barbae, tinea capitis, tinea pedis, tinea unguium"]),
 ],
 spot=["Active scaly edge + central clearing + KOH hyphae — tinea corporis", "T. indotineae + SQLE mutation = terbinafine-resistant tinea (India)", "Scrotum spared in tinea cruris (involved in candidiasis)"],
 note="Doses follow the Indian expert consensus on dermatophytosis (IADVL Task Force); check the department's current protocol."),
]
